ast.span:
contract KCC20SaleV2(
    pubkey listingSeller,
    byte[32] listingTokenId,
    byte[32] listingLockedTokenScriptHash,
    int listingTokenAmount,
    int listingPriceSompi,
    pubkey protocolFeeRecipient,
    int protocolFeeBps
) {
    int constant FEE_DENOMINATOR_BPS = 10000;

    pubkey seller = listingSeller;
    byte[32] tokenId = listingTokenId;
    byte[32] lockedTokenScriptHash = listingLockedTokenScriptHash;
    int tokenAmount = listingTokenAmount;
    int priceSompi = listingPriceSompi;
    pubkey feeRecipient = protocolFeeRecipient;
    int feeBps = protocolFeeBps;

    function requireLockedTokenInput(int tokenInputIndex) {
        require(OpInputCovenantId(tokenInputIndex) == tokenId);
        require(tx.inputs[tokenInputIndex].scriptPubKey == byte[](new ScriptPubKeyP2SH(lockedTokenScriptHash)));
    }

    function requireFeePolicy() {
        require(feeBps >= 0);
        require(feeBps <= FEE_DENOMINATOR_BPS);
    }

    entrypoint function activateListing(sig sellerSig, byte[32] activatedLockedTokenScriptHash, int listingOutputIndex) {
        require(checkSig(sellerSig, seller));
        require(tokenAmount > 0);
        require(priceSompi > 0);
        requireFeePolicy();
        require(OpAuthOutputCount(this.activeInputIndex) == 1);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == listingOutputIndex);
        require(tx.outputs[listingOutputIndex].value == tx.inputs[this.activeInputIndex].value);

        validateOutputState(listingOutputIndex, {
            seller: seller,
            tokenId: tokenId,
            lockedTokenScriptHash: activatedLockedTokenScriptHash,
            tokenAmount: tokenAmount,
            priceSompi: priceSompi,
            feeRecipient: feeRecipient,
            feeBps: feeBps
        });
    }

    entrypoint function buyListing(int tokenInputIndex) {
        requireLockedTokenInput(tokenInputIndex);
        requireFeePolicy();
        require(tokenAmount > 0);
        require(priceSompi > 0);

        int feeSompi = priceSompi * feeBps / FEE_DENOMINATOR_BPS;
        int sellerNet = tx.inputs[this.activeInputIndex].value + priceSompi - feeSompi;
        require(sellerNet > 0);

        byte[34] sellerLock = new ScriptPubKeyP2PK(seller);
        require(tx.outputs[0].value == sellerNet);
        require(tx.outputs[0].scriptPubKey == byte[](sellerLock));
        if (feeSompi > 0) {
            byte[34] feeLock = new ScriptPubKeyP2PK(feeRecipient);
            require(tx.outputs[1].value == feeSompi);
            require(tx.outputs[1].scriptPubKey == byte[](feeLock));
        }
    }

    entrypoint function cancelListing(sig sellerSig, int tokenInputIndex) {
        require(checkSig(sellerSig, seller));
        requireLockedTokenInput(tokenInputIndex);
        require(tokenAmount > 0);
    }
}
